WITH flattened_attrs AS (SELECT id, items, attributes, SIZE(FILTER(items, item -> item.qty >= 3)) AS bulk_lines, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, item) -> acc + item.qty * item.price, acc -> ROUND(acc, 2)) AS cart_value, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, SIZE(attributes) AS num_attributes FROM carts) SELECT id, bulk_lines, LAST_VALUE(bulk_lines, TRUE) OVER (ORDER BY weight_kg, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_bulk_lines, PERCENT_RANK() OVER (ORDER BY weight_kg DESC NULLS LAST) AS weight_kg_percent_rank FROM flattened_attrs WHERE num_attributes BETWEEN 51 AND 52;
